import test from "node:test";
import assert from "node:assert/strict";

import {
	buildXlsx,
	columnIndex,
	columnName,
	looksNumeric,
	parseCsv,
	readXlsx,
	serialToIso,
	sniffDelimiter
} from "../lib/xlsx.js";
import { readZip, writeZip } from "../lib/zip.js";

test("parses quoted CSV with embedded commas and newlines", () => {
	const rows = parseCsv('name,note\n"Ada, A.","line1\nline2"\nBob,"say ""hi"""\n');
	assert.deepEqual(rows, [
		["name", "note"],
		["Ada, A.", "line1\nline2"],
		["Bob", 'say "hi"']
	]);
});

test("sniffs tab-separated text", () => {
	assert.equal(sniffDelimiter("a\tb\tc\n1\t2\t3"), "\t");
	assert.deepEqual(parseCsv("a\tb\n1\t2"), [["a", "b"], ["1", "2"]]);
});

test("maps column letters and indices", () => {
	for (const [index, name] of [[0, "A"], [25, "Z"], [26, "AA"], [701, "ZZ"], [702, "AAA"]]) {
		assert.equal(columnName(index), name);
		assert.equal(columnIndex(name), index);
	}
	assert.equal(columnIndex("1A"), -1);
});

test("only plain numbers become numeric cells", () => {
	for (const value of ["42", "-3.5", "0.25", "1e3"]) assert.equal(looksNumeric(value), true, value);
	for (const value of ["007", "2026-11-23", "1,000", "12px", "", "1e", "0012.5"]) {
		assert.equal(looksNumeric(value), false, value);
	}
});

test("builds a workbook with the expected parts", () => {
	const { buffer, rows, columns, sheetName, formulas } = buildXlsx("名称,数量\n苹果,3\n香蕉,5\n=SUM(B2:B3)\n", { sheetName: "库存" });
	assert.equal(rows, 4);
	assert.equal(columns, 2);
	assert.equal(sheetName, "库存");
	assert.equal(formulas, 1);
	const archive = readZip(buffer);
	assert.deepEqual(archive.names().sort(), [
		"[Content_Types].xml",
		"_rels/.rels",
		"xl/_rels/workbook.xml.rels",
		"xl/styles.xml",
		"xl/workbook.xml",
		"xl/worksheets/sheet1.xml"
	]);
	const sheet = archive.text("xl/worksheets/sheet1.xml");
	assert.match(sheet, /t="inlineStr"/);
	assert.match(sheet, /<f>SUM\(B2:B3\)<\/f>/);
	assert.match(sheet, /<v>3<\/v>/);
	assert.match(sheet, /<pane /);
});

test("round-trips a workbook through build and read", () => {
	const { buffer } = buildXlsx("名称,数量,备注\n苹果,3,红色\n香蕉,5,\n=SUM(B2:B3)\n");
	const result = readXlsx(buffer);
	assert.equal(result.sheets.length, 1);
	assert.equal(result.sheets[0].name, "Sheet1");
	assert.deepEqual(result.sheets[0].rows[0], ["名称", "数量", "备注"]);
	assert.deepEqual(result.sheets[0].rows[1], ["苹果", "3", "红色"]);
	assert.equal(result.sheets[0].rows[3][0], "=SUM(B2:B3)");
	assert.match(result.text, /## Sheet: Sheet1/);
	assert.match(result.text, /苹果\t3\t红色/);
});

test("reads shared strings, inline strings and booleans", () => {
	const sheets = `<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" t="s"><v>0</v></c><c r="B1" t="inlineStr"><is><t>内联</t></is></c><c r="C1" t="b"><v>1</v></c></row></sheetData></worksheet>`;
	const workbook = `<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="数据" sheetId="1" r:id="rId1"/></sheets></workbook>`;
	const rels = `<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`;
	const strings = `<?xml version="1.0"?><sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><si><t>共享</t></si></sst>`;
	const buffer = writeZip([
		{ name: "xl/workbook.xml", data: workbook },
		{ name: "xl/_rels/workbook.xml.rels", data: rels },
		{ name: "xl/sharedStrings.xml", data: strings },
		{ name: "xl/worksheets/sheet1.xml", data: sheets }
	]);
	const result = readXlsx(buffer);
	assert.deepEqual(result.sheets[0].rows[0], ["共享", "内联", "TRUE"]);
});

test("reads a date-formatted cell as ISO text", () => {
	const sheet = `<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" s="1"><v>46389</v></c></row></sheetData></worksheet>`;
	const styles = `<?xml version="1.0"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><cellXfs count="2"><xf numFmtId="0"/><xf numFmtId="14" applyNumberFormat="1"/></cellXfs></styleSheet>`;
	const workbook = `<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="S" sheetId="1" r:id="rId1"/></sheets></workbook>`;
	const rels = `<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`;
	const buffer = writeZip([
		{ name: "xl/workbook.xml", data: workbook },
		{ name: "xl/_rels/workbook.xml.rels", data: rels },
		{ name: "xl/styles.xml", data: styles },
		{ name: "xl/worksheets/sheet1.xml", data: sheet }
	]);
	assert.deepEqual(readXlsx(buffer).sheets[0].rows[0], ["2027-01-02"]);
	assert.equal(serialToIso(1), "1900-01-01");
	assert.equal(serialToIso(46389), "2027-01-02");
});

test("selects one sheet by name and rejects unknown names", () => {
	const workbook = `<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="甲" sheetId="1" r:id="rId1"/><sheet name="乙" sheetId="2" r:id="rId2"/></sheets></workbook>`;
	const rels = `<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/></Relationships>`;
	const sheet = (text) => `<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>${text}</t></is></c></row></sheetData></worksheet>`;
	const buffer = writeZip([
		{ name: "xl/workbook.xml", data: workbook },
		{ name: "xl/_rels/workbook.xml.rels", data: rels },
		{ name: "xl/worksheets/sheet1.xml", data: sheet("一") },
		{ name: "xl/worksheets/sheet2.xml", data: sheet("二") }
	]);
	assert.deepEqual(readXlsx(buffer, { sheet: "乙" }).sheets.map((one) => one.name), ["乙"]);
	assert.equal(readXlsx(buffer, { sheet: "乙" }).sheets[0].rows[0][0], "二");
	assert.throws(() => readXlsx(buffer, { sheet: "丙" }), (error) => error.code === "OFFICE_BAD_ARGS");
});

test("rejects a zip that is not a workbook", () => {
	assert.throws(() => readXlsx(writeZip([{ name: "a.txt", data: "x" }])), (error) => error.code === "OFFICE_BAD_ZIP");
});

test("caps text at maxChars", () => {
	const csv = "a,b\n" + "x,y\n".repeat(200);
	const { buffer } = buildXlsx(csv);
	const result = readXlsx(buffer, { maxChars: 100 });
	assert.equal(result.truncated, true);
	assert.ok(result.text.length <= 100);
});
